insert into policy_registry
  (policy_key, section, title, plain_english, severity, enforced, enforcers, active)
values
  ('A1', 'Data honesty', 'Never invent a number', 'Not a price, not a benchmark, not a square footage, not a utility bill, not a competitor comparison.', 'elevated', true, array['tools/checks/no-fabricated-data.mjs','tools/checks/no-hardcoded-numbers.mjs','supabase/checks/metric_registry.sql','.github/workflows/ci.yml'], true),
  ('A2', 'Data honesty', 'Every figure carries its provenance', 'Who set it, when, and on what basis.', 'elevated', true, array['tools/checks/locked-facts-in-prompts.mjs','tools/checks/no-hardcoded-numbers.mjs','supabase/checks/metric_registry.sql','.github/workflows/ci.yml'], true),
  ('A3', 'Data honesty', 'Absence is explained, never blank', '"No certificate" is unacceptable.', 'elevated', true, array['tools/checks/dead-controls.mjs','tools/checks/no-fabricated-data.mjs','tools/checks/secret-scan.mjs','tools/checks/silent-failures.mjs','.github/workflows/ci.yml'], true),
  ('A4', 'Data honesty', 'Check units before comparing anything', 'Grams per plant against grams per square foot produced a finding wrong by a factor of six.', 'elevated', true, array['supabase/checks/cross_source_reconciliation.sql'], true),
  ('A5', 'Data honesty', 'Never assume business practice — ask', 'Failed material bought at a discount to remediate is a business model, not a loss.', 'elevated', true, array['supabase/checks/metric_registry.sql','supabase/checks/role_clearance.sql','supabase/checks/room_contents.sql'], true),
  ('A6', 'Data honesty', 'Verify against the live system before reporting', 'Every expensive mistake in this build was an unchecked assumption.', 'elevated', false, '{}'::text[], true),
  ('A7', 'Data honesty', 'Correct yourself plainly', 'State the correction, continue.', 'elevated', false, '{}'::text[], true),
  ('B1', 'Weights, units and conversions', 'Convert from the unit Metrc actually recorded', 'Use f_to_pounds().', 'elevated', true, array['supabase/checks/cross_source_reconciliation.sql'], true),
  ('B2', 'Weights, units and conversions', 'Countable items have NO weight', 'Vapes and edibles are units.', 'elevated', false, '{}'::text[], true),
  ('B3', 'Weights, units and conversions', 'Wet and dry are never mixed', 'Fresh frozen is packaged wet; dried flower is not.', 'elevated', false, '{}'::text[], true),
  ('B4', 'Weights, units and conversions', 'Never subtract a dry weight from a wet weight', 'It leaves evaporated water in the total.', 'elevated', true, array['supabase/checks/room_contents.sql'], true),
  ('C0', 'Traceability and proof', 'OWNERSHIP STOPS AT THE COA. NOTHING GETS POSTED WHILE A DISCREPANCY STANDS', 'Owner ruling, 7 August 2026.', 'critical', true, array['tools/checks/literal-licences.mjs','.github/workflows/ci.yml'], true),
  ('C0b', 'Traceability and proof', 'PROOF REQUIRED — "NEVER TESTED" IS A CLAIM, NOT AN EXCUSE', 'Owner hard rule, 8 August 2026.', 'elevated', false, '{}'::text[], true),
  ('C0a', 'Traceability and proof', 'PARSE FOR NEW DATA ON EVERY ACCESS', 'Owner ruling, 7 August 2026. Every agent, every session, before it reports anything: check what has arrived since it last looked and parse it. Documents land in metrc_documents and sit unread.', 'elevated', false, '{}'::text[], true),
  ('C1', 'Traceability and proof', 'Every tile, total and headline is a CLAIM and must open to the individual items behind it', 'No summarising, no sampling, no top-N.', 'elevated', true, array['tools/checks/tile-drills.mjs','supabase/checks/metric_registry.sql','supabase/checks/reconcile_tiles.sql','.github/workflows/ci.yml'], true),
  ('C2', 'Traceability and proof', 'Totals must reconcile to the items', 'If a tile says 1,943.6 lb, the rows behind it must add to 1,943.6 lb.', 'elevated', true, array['tools/checks/aggregate-count.mjs','tools/checks/no-hardcoded-numbers.mjs','supabase/checks/metric_registry.sql','supabase/checks/reconcile_tiles.sql','.github/workflows/ci.yml'], true),
  ('C3', 'Traceability and proof', 'Every product, everywhere, shows: THC, terpenes, manufacturer, certificate, manifest', 'Missing ones state why.', 'elevated', false, '{}'::text[], true),
  ('C3a', 'Traceability and proof', 'EVERY ITEM ROW IN EVERY DRILL-DOWN CARRIES ITS CERTIFICATE AND ITS MANIFEST — sitewide, every time', 'Owner-set 7 August 2026, binding. Not a link to a document page.', 'elevated', false, '{}'::text[], true),
  ('C4', 'Traceability and proof', 'Location always carries its dates', 'Entered, how long there, when it left, where it went.', 'elevated', false, '{}'::text[], true),
  ('C5', 'Traceability and proof', 'Testing always states the date out, the date back, and days at the laboratory', 'Use f_test_status(): OUT FOR TESTING, NO TESTING PLANNED YET, PASSED, FAILED — sitewide, driven by Metrc state.', 'elevated', false, '{}'::text[], true),
  ('C6', 'Traceability and proof', 'Ours versus third party splits on the face of the tile — for failed material AND for revenue', 'With the supplier named.', 'elevated', false, '{}'::text[], true),
  ('C6a', 'Traceability and proof', 'Third-party failed material is an INPUT, not a problem', 'It is bought at a discount deliberately, then either remediated and processed in-house, or sold on to another licensee who remediates it.', 'elevated', false, '{}'::text[], true),
  ('C6b', 'Traceability and proof', 'Our own failed material needs a recorded DISPOSITION, and there are three', 'Remediate in-house · sell on for remediation · destroy.', 'elevated', false, '{}'::text[], true),
  ('C6c', 'Traceability and proof', 'There are THREE revenue lines and they are never blended', 'Extended again 7 August 2026: Twisted Growers is a cultivator, a manufacturer and a wholesale distributor — it takes on other licensees'' product to sell.', 'elevated', false, '{}'::text[], true),
  ('C6d', 'Traceability and proof', 'SERVICES are a fourth line, and on services WE DO NOT OWN THE MATERIAL', 'Added 7 August 2026: Twisted Growers also offers white label manufacturing and trim tolling.', 'elevated', false, '{}'::text[], true),
  ('D1', 'Metrc', 'Metrc is the legal record. This platform is a READ-ONLY MIRROR', 'It has no write credentials.', 'elevated', false, '{}'::text[], true),
  ('D2', 'Metrc', 'Never correct a Metrc problem only in this platform', 'That hides it from the state record.', 'elevated', true, array['supabase/checks/room_contents.sql'], true),
  ('D3', 'Metrc', 'Metrc-facing tasks do not clear until fixed at source', null, 'elevated', false, '{}'::text[], true),
  ('D4', 'Metrc', 'IDENTITY IS THE TAG. NAMES RESOLVE METRC → COA → MANIFEST → A PERSON', 'Owner ruling, 9 August 2026: "we have to always match names to Metrc, then COA and manifests" · "by tag" · "it''s seed to sale Metrc".', 'elevated', false, '{}'::text[], true),
  ('E1', 'Database safety', 'NEVER drop view … cascade', 'It destroyed mv_department_dashboard three times and blanked every dashboard with no error.', 'elevated', true, array['tools/checks/guard-fixtures.mjs','tools/hooks/guard-sql.mjs','.github/workflows/ci.yml'], true),
  ('E2', 'Database safety', 'Re-query after every connector error and after every structural change', 'Errors lie in both directions.', 'elevated', false, '{}'::text[], true),
  ('E3', 'Database safety', 'Matviews read base tables, never other views', 'So a view rebuild cannot cascade into them.', 'elevated', true, array['supabase/checks/nightly_platform_check.sql'], true),
  ('E4', 'Database safety', 'Aggregate views: use sum(packages), not count(*)', null, 'elevated', true, array['tools/checks/aggregate-count.mjs','.github/workflows/ci.yml'], true),
  ('E5', 'Database safety', 'Functions that views depend on need set search_path = public', null, 'elevated', true, array['supabase/checks/nightly_platform_check.sql'], true),
  ('E6', 'Database safety', 'Never grant … to anon', '36 views once leaked package tags, suppliers and dollar figures to anyone holding the publishable key.', 'elevated', true, array['tools/checks/guard-fixtures.mjs','tools/hooks/guard-sql.mjs','.github/workflows/ci.yml'], true),
  ('F1', 'Front-end safety', 'Anchor scripted edits on the function signature', 'Never on a common line like const [busy, setBusy].', 'elevated', true, array['tools/checks/eslint-ratchet.mjs'], true),
  ('F2', 'Front-end safety', 'Never deploy what you have not looked at', 'As a signed-in user.', 'elevated', true, array['.github/workflows/ci.yml'], true),
  ('F3', 'Front-end safety', 'No text may overlap or be silently truncated', 'Wrap; never clip.', 'elevated', false, '{}'::text[], true),
  ('F4', 'Front-end safety', 'No abbreviations', '"Unit of measure", not "UOM".', 'elevated', true, array['tools/checks/ui-language.mjs','.github/workflows/ci.yml'], true),
  ('F5', 'Front-end safety', 'Use the whole page', 'No wasted space in critical workspace, no horizontal scrollbars, no cut-off labels.', 'elevated', false, '{}'::text[], true),
  ('G1', 'Configuration', 'Nothing is hardcoded', 'Every threshold, rate and licence is a database row an authorised user can change.', 'elevated', true, array['tools/checks/aggregate-count.mjs','tools/checks/apex-registry-vs-spec.mjs','tools/checks/literal-licences.mjs','tools/checks/no-hardcoded-numbers.mjs','supabase/checks/hardcoded_thresholds.sql','.github/workflows/ci.yml'], true),
  ('G2', 'Configuration', 'Licences come from company_licenses via f_is_ours()', 'Never literals.', 'elevated', true, array['tools/checks/docs-vs-database.mjs','tools/checks/literal-licences.mjs','tools/checks/no-duplicate-rows.mjs','.github/workflows/ci.yml'], true),
