  ('H2', 'Issues and accountability', 'Forensic records are immutable', 'watchdog_findings, issue_decisions, cost_input_history, metrc_corrections and moisture_loss_entries cannot be deleted.', 'elevated', true, array['tools/checks/guard-fixtures.mjs','tools/hooks/guard-sql.mjs','supabase/checks/fortifications.sql','supabase/checks/nightly_platform_check.sql','.github/workflows/ci.yml'], true),
